"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[458],{1462:(e,a,o)=>{o.d(a,{FadeIn:()=>l});var r=o(8886),t=o(6435),i=o(6685),s=o(9398),n=o(3939);let c={up:{y:1,x:0},down:{y:-1,x:0},left:{x:1,y:0},right:{x:-1,y:0},none:{x:0,y:0}};function l(e){let{children:a,className:o,direction:l="up",distance:p=30,delay:d=0,once:m=!0}=e,u=(0,t.I)(),h=c[l],[y,f]=(0,s.useState)(!1);return((0,s.useEffect)(()=>f(!0),[]),!y||u)?(0,r.jsx)("div",{className:(0,n.cn)(o),children:a}):(0,r.jsx)(i.P.div,{initial:{opacity:0,x:h.x*p,y:h.y*p},whileInView:{opacity:1,x:0,y:0},viewport:{once:m,margin:"-80px"},transition:{type:"spring",damping:25,stiffness:120,delay:d},className:(0,n.cn)(o),children:a})}},6063:(e,a,o)=>{o.d(a,{AM:()=>u,Ky:()=>g,Qe:()=>y,V3:()=>h,XT:()=>w,YX:()=>b,mG:()=>f,sF:()=>m});var r=o(1348),t=o(6636),i=o(724),s=o(2475),n=o(3494),c=o(2760),l=o(8658),p=o(8490),d=o(9326);let m={hero:{h1Lead:"Spray foam contractor insurance that covers",h1Highlight:"the rig, the chemical, and the claim",subcopy:"General liability built for spray foam, off-ratio coverage, contractor pollution liability for VOC and isocyanate exposure, workers' comp, commercial auto for spray rigs, tools and equipment, umbrella, and bonds — purpose-built for spray foam insulation contractors. A-rated carriers. 15-minute quotes.",statValue:"Spray foam contractors",statLabel:"Insured nationwide — applicators, insulation businesses, and specialty crews",imageAlt:"Spray foam contractor applying closed-cell foam insulation in a commercial building"},nav:{ariaLabel:"Spray Foam Insurance Agency home"},footer:{ctaTitle:"Ready to protect your spray foam business?",ctaSubcopy:"15-minute quotes. 2-hour claims response. Insurance for spray foam contractors and insulation businesses nationwide.",description:"Specialized insurance for spray foam insulation contractors — GL with spray foam endorsements, off-ratio coverage, contractor pollution liability for VOC and isocyanate exposure, workers' comp, commercial auto for spray rigs, tools and equipment, umbrella, and bonds. A division of Contractors Choice Agency — founded 2005, licensed all 50 states."},servicesGrid:{h2Lead:"Coverage built specifically for",h2Highlight:"spray foam contractors",lead:"Standard contractor policies exclude the chemical-application exposure, off-ratio risk, and pollution claims that define spray foam work. We build programs designed for the actual risks of spray polyurethane foam insulation."},why:{eyebrow:"Why spray foam contractors switch to us",h2Lead:"The coverage gaps that",h2Highlight:"cost spray foam contractors the most",lead:"Most insurance agents hand a spray foam contractor a generic GL policy and call it done. Then an off-ratio event, a VOC exposure claim, or a completed-operations lawsuit hits — and the exclusion language kicks in. We underwrite the parts of your operation everyone else leaves out.",sidebarTitle:"Run by people who know the trades",sidebarBody:"Contractors Choice Agency was founded in 2005 by people from the contractor world. We know what spray foam equipment costs, what a proportioner failure looks like, and what happens when a chemical exposure claim lands."},coverage:{eyebrow:"Where we write",h2Lead:"Spray foam contractor coverage.",h2Highlight:"All 50 states.",lead:"From Texas and Florida to the Northeast and Pacific Northwest, Contractors Choice Agency writes spray foam insurance in every state where insulation contractors operate.",imageAlt:"Spray foam insulation contractor applying foam in a residential attic — national spray foam insurance coverage",badgeTitle:"National coverage for spray foam contractors.",badgeSub:"Writing spray foam programs in all 50 states since 2005."},process:{lead:"No generic forms, no two-week delays. A real conversation about your foam operation, real markets that understand the chemical exposure, and a program you can actually understand — fast."},finalCta:{h2Lead:"Protect Your Spray Foam Business",h2Highlight:"with coverage built for the chemical risk.",lead:"Whether you need a GL policy with proper spray foam endorsements today, or a full program — CPL, off-ratio, workers' comp, auto, and tools — one call gets you real quotes from specialty markets that know the trade. Not a voicemail and a two-week wait."},ctaBand:{defaultTitle:"Ready to protect your spray foam operation?",defaultDescription:"Get a 15-minute quote from specialists who understand spray foam insulation — off-ratio risk, VOC and isocyanate exposure, equipment-intensive operations, and chemical-application liability."},faq:{defaultTitleLead:"Spray foam contractor insurance,",defaultTitleHighlight:"in plain English"},servicesPage:{metaTitle:"Spray Foam Contractor Insurance Coverage & Services",metaDescription:"Eight lines of insurance built for spray foam contractors: GL with spray foam endorsements, off-ratio coverage, contractor pollution liability, workers' comp, commercial auto, tools and equipment, umbrella, and bonds. Licensed all 50 states.",h1Lead:"Insurance built line-by-line for",h1Highlight:"spray foam contractors",lead:"Each policy below addresses a specific exposure in spray foam insulation work — from the GL exclusions that catch foam contractors off guard to the contractor pollution liability your standard policy leaves out.",ogTitle:"Spray Foam Contractor Insurance Coverage | Contractors Choice Agency",ogDescription:"GL with spray foam endorsements, off-ratio coverage, contractor pollution liability, workers' comp, commercial auto, tools and equipment, umbrella, and bonds — written specifically for spray foam insulation contractors.",ctaTitle:"Not sure which lines you need?",ctaDescription:"Most spray foam contractors bundle GL + CPL + off-ratio + workers' comp + tools into one coordinated program. We'll build the right mix in one call."},blogPage:{metaTitle:"Spray Foam Contractor Insurance Blog — Guides & Insights",metaDescription:"Practical insurance guidance for spray foam contractors: GL exclusions, off-ratio coverage, contractor pollution liability, workers' comp class codes, and commercial auto for spray rigs.",h1Lead:"Spray foam contractor insurance,",h1Highlight:"decoded",lead:"Plain-English guides on the coverage that matters for spray foam insulation businesses — off-ratio risk, VOC and isocyanate liability, GL exclusions, and workers' comp for applicator crews.",ogTitle:"Spray Foam Contractor Insurance Blog | Contractors Choice Agency",ogDescription:"Practical insurance guidance for spray foam contractors: GL exclusions, off-ratio coverage, contractor pollution liability, workers' comp class codes, and commercial auto for spray rigs."},serviceDetail:{h1Suffix:"for spray foam contractors",imageAltSuffix:"spray foam insulation contracting",category:"Spray Foam Contractor Insurance"},about:{metaTitle:"About Spray Foam Insurance Agency | Contractors Choice Agency",metaDescription:"Spray Foam Insurance Agency is the spray foam–focused division of Contractors Choice Agency, founded in 2005. GL with spray foam endorsements, off-ratio coverage, CPL, and workers' comp for spray foam contractors. Licensed all 50 states.",h1Lead:"Built by people who know the trades,",h1Highlight:"for spray foam contractors",lead:"Spray Foam Insurance Agency is the spray foam–focused division of Contractors Choice Agency — founded in 2005 by Josh Cotner, who knows exactly what happens when a GL exclusion or a missing CPL policy shows up in a claim denial for a spray foam contractor.",imageAlt:"A spray foam contractor in full PPE applying closed-cell foam insulation on a commercial jobsite",storyEyebrow:"Our story",storyTitle:"From the jobsite to the agency.",storyLead:"Josh Cotner ran equipment, read specs, and filed certificates before founding CCA in 2005. That background is why we understand what's at stake when a spray foam contractor's GL policy excludes the claim or a CPL is missing and a VOC exposure lands.",valuesTitle:"Four things we won't compromise on.",timeline:[{year:"2005",title:"Contractors Choice Agency founded",desc:"Josh Cotner opens CCA in Chandler, AZ, after years working in the trades — built to insure contractors, specialty operators, and trades the right way."},{year:"10 yrs",title:"Expanded to specialty contractor markets",desc:"After placing programs for dozens of specialty trades, CCA extends deep expertise to high-risk chemical applicators including spray foam, polyurea, and insulation contractors."},{year:"Today",title:"Dedicated spray foam division",desc:"Spray Foam Insurance Agency focuses CCA's expertise on spray polyurethane foam contractors — operations where off-ratio risk, CPL, and GL exclusions are the real exposures."}],values:[{icon:"HardHat",title:"Contractor-first, always",desc:"Josh spent years in the trades before starting the agency. We speak the language of spray foam contracting because we know what happens when coverage fails at claim time."},{icon:"ShieldCheck",title:"Coverage that closes the gaps",desc:"GL exclusions for chemical application, missing CPL, no off-ratio coverage — we address the risks standard contractor markets miss entirely."},{icon:"Award",title:"A-rated markets only",desc:"We shop carriers with the financial strength and contractor experience to be there when an off-ratio event, a pollution claim, or a completed-operations lawsuit hits."},{icon:"Handshake",title:"Honest, no-pressure advice",desc:"If you don't need a line of coverage, we'll tell you. We earn trust by being straight about what your spray foam operation actually requires."}]},quote:{h1Lead:"Get your",h1Highlight:"spray foam contractor insurance quote",lead:"Tell us about your spray foam operation. We'll shop A-rated specialty markets and come back with real quotes in about 15 minutes — no obligation.",businessPlaceholder:"Apex Spray Foam LLC",emailPlaceholder:"owner@apexsprayfoam.com",phonePlaceholder:"(512) 555-0100",messagePlaceholder:"Jobs you do (residential, commercial, roofing), equipment and rig count, crew size, states where you work, coverage lines needed, current insurer, loss history, or anything else that helps us quote accurately…",errorMessage:"Something went wrong. Please call us at 844-967-5247 or try again.",trustNicheTitle:"Built for spray foam contractors",trustNicheDesc:"Policies written for spray foam operations — not generic contractor coverage."},contact:{h1Lead:"Let's talk about your",h1Highlight:"spray foam contractor coverage",lead:"Questions, a quote, or a claim — reach a person who knows spray foam insulation, not a queue.",errorMessage:"Something went wrong. Please call us at 844-967-5247."},coveragePage:{metaTitle:"Spray Foam Contractor Insurance — National Coverage, All 50 States",metaDescription:"Contractors Choice Agency writes spray foam contractor insurance in all 50 states — Texas, Florida, the Northeast, Midwest, California, Mountain States, and everywhere spray foam insulation contractors operate.",h1Lead:"National reach.",h1Highlight:"All 50 states, every spray foam market.",lead:"Contractors Choice Agency places spray foam insurance programs in all 50 states — from Texas and Florida to the Northeast, Midwest, and Pacific Northwest.",sectionTitle:"Spray foam contractor regions we serve.",nationwideLead:"Whether your spray foam business is in Texas, Florida, the Northeast, the Mountain States, or anywhere in between — one agent, one coordinated program. NPN #8608479.",faqs:[{q:"Do you only insure spray foam contractors in certain states?",a:"No. Contractors Choice Agency is licensed in all 50 states and writes spray foam programs for contractors anywhere in the country — Texas, Florida, the Northeast, Midwest, California, Mountain States, Pacific Northwest, and everywhere in between."},{q:"Can you write coverage if we work across state lines?",a:"Yes. We structure programs so your GL, CPL, workers' comp, and commercial auto coordinate across state lines without gaps — including spray rigs that travel for commercial and industrial jobs."},{q:"Do you understand the specific risks in my state's spray foam market?",a:"Yes. We work with specialty markets that understand regional differences — California VOC regulations, Texas high-volume new construction, Northeast retrofit work, and Mountain State cold-weather application risk."},{q:"Can you coordinate coverage across multiple jobsites and locations?",a:"Yes. If you operate crews across multiple states or have multiple rigs, we build one coordinated program that covers all locations, vehicles, and crews with no gaps."}]}},u=[{step:"01",icon:r.A,title:"Tell us about your spray foam operation",description:"15-min call or form. Crew size, equipment, jobs you do (residential, commercial, roofing), states where you work, and the coverage lines you need."},{step:"02",icon:t.A,title:"We shop specialty contractor markets",description:"Niche markets that actually write spray foam GL with proper endorsements, off-ratio coverage, and CPL — not generic contractor forms that carve out chemical application."},{step:"03",icon:i.A,title:"Bind a program built for foam work",description:"GL + CPL + off-ratio + workers' comp + tools + auto, coordinated so there are no gaps across your rig, your crew, and your completed jobs."},{step:"04",icon:s.A,title:"Claims support that moves fast",description:"When an off-ratio event, a VOC complaint, or a property-damage claim arrives, you reach a person who knows spray foam — not a queue. 2-hour response."}],h=[{icon:s.A,title:"GL built for spray foam — not a generic form",description:"Most contractor GL policies exclude chemical application, restrict completed-operations for foam, or cap coverage at amounts that don't reflect the real cost of a spray foam claim. We place forms that match the actual exposure."},{icon:n.A,title:"Off-ratio coverage no one else offers",description:"When the A:B component ratio is wrong, foam doesn't cure right — and the resulting property damage and chemical exposure claims are excluded by nearly every standard GL. We place off-ratio as a distinct, insurable risk."},{icon:c.A,title:"CPL for VOC and isocyanate exposure",description:"Spray foam releases volatile organic compounds and MDI isocyanates that can cause third-party bodily injury claims. Standard GL excludes these under the pollution exclusion. Contractor Pollution Liability closes that gap."},{icon:l.A,title:"Equipment coverage for proportioners and rigs",description:"A proportioning machine alone can be worth $80,000+. Tools and equipment coverage insures your spray guns, heated hoses, generators, and rigs against theft, damage, and breakdown on the jobsite."},{icon:p.A,title:"Workers' comp with correct class codes",description:"Spray foam workers' comp is often miscoded under generic insulation or painting codes, resulting in audit surprises and coverage gaps. We assign codes to your actual workflow — applicators, helpers, and supervisors."},{icon:d.A,title:"Commercial auto for spray rigs on the road",description:"A rig with a proportioner and chemical tanks is not just a pickup truck. We structure commercial auto for the vehicle, the equipment on it, and the liability when a spray rig is in transit or parked on a jobsite."}],y=[{q:"What insurance does a spray foam contractor need?",a:"A working spray foam contractor typically needs general liability with spray foam endorsements, contractor pollution liability (CPL) for VOC and isocyanate exposure, off-ratio coverage for A:B component mix errors, workers' compensation, commercial auto for spray rigs, tools and equipment coverage, a commercial umbrella, and contractor bonds. Most spray foam businesses carry all eight as one coordinated program."},{q:"How much does spray foam contractor insurance cost?",a:"Cost depends on annual revenue, crew size, types of jobs (residential, commercial, industrial), states where you work, equipment value, and loss history. Small residential-only spray foam contractors may pay a few thousand a year; larger commercial operations with significant equipment and payroll run considerably more. We quote your actual operation in about 15 minutes — never a generic estimate."},{q:"Does a standard contractor GL policy cover spray foam work?",a:"Often not. Most generic contractor GL policies contain exclusions for chemical application, completed-operations for foam products, or pollution events from VOCs and isocyanates. Spray foam contractors need GL forms that include proper spray foam endorsements and don't carve out the primary risks of the trade."},{q:"What is off-ratio coverage and why do I need it?",a:"Off-ratio occurs when the A-component (isocyanate) and B-component (polyol) in spray polyurethane foam are mixed at the wrong ratio. The foam doesn't cure correctly, can off-gas harmful chemicals, and causes property damage — claims that are explicitly excluded by most standard GL policies. Off-ratio coverage insures this specific risk as a standalone event."},{q:"What is Contractor Pollution Liability (CPL) for spray foam?",a:"CPL covers third-party bodily injury and property damage from chemical releases during spray foam application — VOC off-gassing, MDI isocyanate exposure, blowing agent releases, and related events. Standard GL policies exclude these under the pollution exclusion. CPL fills that gap."},{q:"Are VOC and isocyanate exposure claims covered by standard GL?",a:"No. Volatile organic compounds and MDI isocyanates released during spray foam application are treated as pollutants under standard GL policies, placing those claims under the pollution exclusion. Only a dedicated Contractor Pollution Liability policy covers bodily injury and property damage from chemical exposure."},{q:"Do I need workers' comp if I have spray foam employees?",a:"In most states, yes — workers' comp is required once you have employees, and spray foam work is high-hazard. Chemical inhalation, confined-space exposure, fall hazards, and exothermic reaction burns are common injury patterns. Proper workers' comp with correct class codes for spray foam crews is essential."},{q:"What class codes apply to spray foam workers?",a:"Spray foam workers are often miscoded under generic insulation (class code 5473) or painting codes. The correct code matters because it affects premium, coverage scope at audit, and whether a chemical-exposure injury is properly recognized. We assign codes to your actual workflow — applicators, helpers, and estimators."},{q:"Is my spray rig or proportioning machine covered under commercial auto?",a:"The proportioner and equipment mounted on the rig are not automatically covered by auto insurance — they need inland marine or tools and equipment coverage. The vehicle itself needs commercial auto with proper endorsements for equipment-carrying vehicles. We coordinate both so there's no gap."},{q:"What equipment should I insure as a spray foam contractor?",a:"At minimum: your proportioning machine, spray gun and hoses, heated hose set, transfer pumps, generators, and the vehicle the equipment rides on. A proportioner alone can be worth $60,000–$120,000. Tools and equipment coverage insures these against theft, damage, and breakdown on or off the jobsite."},{q:"Does commercial umbrella cover spray foam claims?",a:"Yes — commercial umbrella sits above your GL, auto, and workers' comp to cover claims that exceed underlying limits. Given that a single off-ratio event or fire claim can run into the hundreds of thousands, most spray foam contractors doing commercial work should carry an umbrella."},{q:"Do I need a bond to work as a spray foam contractor?",a:"Many states require a contractor license bond as a condition of licensing. General contractors and commercial project owners often require performance and payment bonds for spray foam subcontractors. We issue contractor bonds quickly — often same-day — and coordinate them with your liability program."},{q:"Can you insure a spray foam contractor who has been declined before?",a:"Often yes. We have admitted and excess-and-surplus (E&S) markets for spray foam contractors declined over prior claims, CPL history, high chemical exposure, or other issues. Bring us what you have and we'll find a market."},{q:"What happens if I do both open-cell and closed-cell spray foam?",a:"Both types carry similar liability exposures but different application risks. Open-cell foam is more common in residential applications; closed-cell is used in commercial, roofing, and cold-climate work. We account for both in the program — including the higher chemical concentrations in closed-cell applications."},{q:"Is spray foam roofing covered the same as standard spray foam?",a:"Not automatically. Spray polyurethane foam (SPF) roofing systems involve additional exposures — roof-level fall hazards, UV coating application, and different completed-operations claims patterns. We specifically address roofing foam application in the GL and CPL so those jobs are covered."},{q:"What if a homeowner claims the spray foam damaged their home?",a:"Property-damage completed-operations claims — foam expansion into HVAC systems, incorrect application causing structural issues, or off-ratio foam that must be removed — are covered under a properly structured GL policy with spray foam endorsements. Without those endorsements, the claim can be excluded."},{q:"Do you write spray foam contractor insurance in all 50 states?",a:"Yes. Contractors Choice Agency is licensed in all 50 states and has markets for spray foam operations whether your business is in Texas, Florida, the Northeast, Midwest, California, or anywhere in between."},{q:"How fast can we get a spray foam contractor insurance quote?",a:"Typically 15 minutes on a call. For larger programs with significant commercial work or high equipment values, we may need a day or two to involve the right markets — but we move fast and tell you the timeline up front."},{q:"Should I bundle all my spray foam coverage with one program?",a:"Usually yes. Bundling GL + CPL + workers' comp + auto + tools into one coordinated program closes gaps between policies — especially between GL and CPL where most spray foam claims fall in the gray zone — and is typically cheaper and easier to manage at claim time."},{q:"Can I get insurance if I just started my spray foam business?",a:"Yes. New spray foam contractors can be harder to place with some markets, but we have programs for startups and recently-established businesses. The key is having proper equipment, PPE protocols, and training in place — we'll help you document what underwriters want to see."}],f=[{name:"Texas & Southwest",note:"TX, AZ, NM, NV — high-volume new construction and commercial foam markets"},{name:"Southeast",note:"FL, GA, NC, SC — humidity-driven insulation demand and coastal construction"},{name:"Midwest",note:"IL, IN, OH, MI, MN — cold-climate residential and commercial foam work"},{name:"Northeast",note:"NY, PA, NJ, CT, MA — aging housing stock retrofits and tight energy codes"},{name:"California",note:"CA — Title 24 energy codes and strict VOC regulations"},{name:"Mountain States",note:"CO, UT, ID, WY — cold-weather application and booming construction"},{name:"Mid-Atlantic",note:"VA, MD, DC, DE — residential retrofits, commercial builds, federal projects"},{name:"Pacific Northwest",note:"WA, OR, ID — energy efficiency codes and environmental regulations"}],g=["Alabama","Alaska","Arizona","Arkansas","California","Colorado","Connecticut","Delaware","Florida","Georgia","Hawaii","Idaho","Illinois","Indiana","Iowa","Kansas","Kentucky","Louisiana","Maine","Maryland","Massachusetts","Michigan","Minnesota","Mississippi","Missouri","Montana","Nebraska","Nevada","New Hampshire","New Jersey","New Mexico","New York","North Carolina","North Dakota","Ohio","Oklahoma","Oregon","Pennsylvania","Rhode Island","South Carolina","South Dakota","Tennessee","Texas","Utah","Vermont","Virginia","Washington","West Virginia","Wisconsin","Wyoming"],w=["General Liability for Spray Foam","Off-Ratio Coverage","Contractor Pollution Liability (CPL)","Workers' Compensation","Commercial Auto / Spray Rigs","Tools & Equipment Coverage","Commercial Umbrella","Contractor Bonds","Full program / bundle (recommended)","Not sure — help me figure it out"],b=["Less than 1 year","1–2 years","3–5 years","6–10 years","10+ years"]}}]);